insert into public.programs (id, kind, name, college, catalog, min_total_credits, min_gpa, notes, source_url, sort_order, excluded_programs, parent_id) values
('eng-civil', 'degree', 'BS Civil Engineering', 'College of Engineering', 'College of Engineering, admitted 2026-2027', 131, 2.0, 'Curriculum for students who started at Ohio State in Autumn 2025 or later (MATH 1151 start: 131 credit hours). Major courses need admission to the major. No course counts twice across the core selection, design, lab, and technical elective requirements. Ohio State requires a 2.00 cumulative GPA to graduate; a D or better passes a course, but some prerequisites need C- or better.', 'https://ceg.osu.edu/civil-engineering-curriculum', 200, '{}'::text[], null),
('eng-environmental', 'degree', 'BS Environmental Engineering', 'College of Engineering', 'College of Engineering, admitted 2026-2027', 130, 2.0, 'Curriculum for students who started at Ohio State in Autumn 2025 or later (MATH 1151 start: 130 credit hours). Students who need math before MATH 1151 will need extra time. Ohio State requires a 2.00 cumulative GPA to graduate; a D or better passes a course, but some prerequisites need C- or better.', 'https://ceg.osu.edu/environmental-engineering-curriculum', 201, '{}'::text[], null),
('eng-mechanical', 'degree', 'BS Mechanical Engineering', 'College of Engineering', 'College of Engineering, admitted 2026-2027', 130, 2.0, 'Suggested 8-semester plan for students starting in MATH 1151 (130 credit hours). Major courses need enrollment as a MechEng-BS student. Take the GE Writing course before MECHENG 3870. Mechanical Engineering students need a 2.0 cumulative GPA to graduate.', 'https://mae.osu.edu/me-students-starting-math-1151', 202, '{}'::text[], null),
('eng-aerospace', 'degree', 'BS Aerospace Engineering', 'College of Engineering', 'College of Engineering, admitted 2026-2027', 128, 2.0, 'Suggested 8-semester plan for students starting in MATH 1151 (128 credit hours). Most AEROENG courses are restricted to Aerospace majors and offered once a year. Aerospace Engineering students need a 2.0 cumulative GPA to graduate.', 'https://mae.osu.edu/students-starting-math-1151', 203, '{}'::text[], null),
('eng-welding', 'degree', 'BS Welding Engineering', 'College of Engineering', 'College of Engineering, admitted 2026-2027', 129, 2.0, '2026-2027 curriculum sheet (revised 10/19/2026), 129 credit hours. Direct admission; MATSCEN 2010 with a C or higher is required before the spring major courses, and major courses start in spring. Ohio State requires a 2.00 cumulative GPA to graduate; a D or better passes a course, but some prerequisites need C- or better.', 'https://advising.engineering.osu.edu/media/document/2026-10-19/00-we-26-27-updated-curriculum-sheet-curriculum-change_0.pdf', 204, '{}'::text[], null),
('eng-ece', 'degree', 'BS Electrical and Computer Engineering', 'College of Engineering', 'College of Engineering, admitted 2026-2027', 128, 2.0, 'One degree with two programs of study: Electrical Engineering and Computer Engineering (choose one as your specialization). Requirements from the 2026-2027 bingo sheets (updated 8/20/2026). Minimum 128 credit hours; at least 30 hours of ECE courses at Ohio State; 30 hours of basic math and science; 2.0 cumulative GPA to graduate. No more than 3 credit hours of S/U coursework in the electives.', 'https://ece.osu.edu/worksheets-curricula-information', 205, '{}'::text[], null),
('eng-ece-ee', 'specialization', 'Electrical Engineering', 'College of Engineering', 'College of Engineering, admitted 2026-2027', null, null, null, 'https://ece.osu.edu/media/document/2026-08-20/2026-2027-ee-bingo-sheet-8-20-26.docx', 206, '{}'::text[], 'eng-ece'),
('eng-ece-ce', 'specialization', 'Computer Engineering', 'College of Engineering', 'College of Engineering, admitted 2026-2027', null, null, null, 'https://ece.osu.edu/media/document/2026-08-20/2026-2027-ce-bingo-sheet-8-20-26.docx', 207, '{}'::text[], 'eng-ece'),
('eng-engphys', 'degree', 'BS Engineering Physics', 'College of Engineering', 'College of Engineering, admitted 2026-2027', 131, 2.0, '2026-2027 curriculum sheet for students starting in MATH 1151 (revised 6/9/2026), 131 credit hours. Choose one of eight engineering specializations (27 credit hours). Ohio State requires a 2.00 cumulative GPA to graduate; a D or better passes a course, but some prerequisites need C- or better.', 'https://physics.osu.edu/engineering-physics-program/engineering-physics-degree-requirements', 208, '{}'::text[], null),
('eng-engphys-aero', 'specialization', 'Aerospace Engineering (Engineering Physics)', 'College of Engineering', 'College of Engineering, admitted 2026-2027', null, null, null, 'https://physics.osu.edu/engineering-physics-program/engineering-physics-degree-requirements', 209, '{}'::text[], 'eng-engphys'),
('eng-engphys-chem', 'specialization', 'Chemical Engineering (Engineering Physics)', 'College of Engineering', 'College of Engineering, admitted 2026-2027', null, null, null, 'https://physics.osu.edu/engineering-physics-program/engineering-physics-degree-requirements', 210, '{}'::text[], 'eng-engphys'),
('eng-engphys-cse', 'specialization', 'Computer Science and Engineering (Engineering Physics)', 'College of Engineering', 'College of Engineering, admitted 2026-2027', null, null, null, 'https://physics.osu.edu/engineering-physics-program/engineering-physics-degree-requirements', 211, '{}'::text[], 'eng-engphys'),
('eng-engphys-ece', 'specialization', 'Electrical and Computer Engineering (Engineering Physics)', 'College of Engineering', 'College of Engineering, admitted 2026-2027', null, null, null, 'https://physics.osu.edu/engineering-physics-program/engineering-physics-degree-requirements', 212, '{}'::text[], 'eng-engphys'),
('eng-engphys-ise', 'specialization', 'Industrial and Systems Engineering (Engineering Physics)', 'College of Engineering', 'College of Engineering, admitted 2026-2027', null, null, null, 'https://physics.osu.edu/engineering-physics-program/engineering-physics-degree-requirements', 213, '{}'::text[], 'eng-engphys'),
('eng-engphys-mse', 'specialization', 'Materials Science and Engineering (Engineering Physics)', 'College of Engineering', 'College of Engineering, admitted 2026-2027', null, null, null, 'https://physics.osu.edu/engineering-physics-program/engineering-physics-degree-requirements', 214, '{}'::text[], 'eng-engphys'),
('eng-engphys-mech', 'specialization', 'Mechanical Engineering (Engineering Physics)', 'College of Engineering', 'College of Engineering, admitted 2026-2027', null, null, null, 'https://physics.osu.edu/engineering-physics-program/engineering-physics-degree-requirements', 215, '{}'::text[], 'eng-engphys'),
('eng-engphys-nuclear', 'specialization', 'Nuclear Engineering (Engineering Physics)', 'College of Engineering', 'College of Engineering, admitted 2026-2027', null, null, null, 'https://physics.osu.edu/engineering-physics-program/engineering-physics-degree-requirements', 216, '{}'::text[], 'eng-engphys'),
('eng-materials', 'degree', 'BS Materials Science and Engineering', 'College of Engineering', 'College of Engineering, admitted 2026-2027', 127, 2.0, 'Curriculum sheet revised 10/19/2026 (127 credit hours; the sheet''s heading still says 2025-2026). Direct admission; major courses start in spring after MATSCEN 2010 with a C or higher. Focus areas: Biomaterials, Ceramics, Electronic Materials, Metallurgy, or Polymers (chosen through electives). Ohio State requires a 2.00 cumulative GPA to graduate; a D or better passes a course, but some prerequisites need C- or better.', 'https://advising.engineering.osu.edu/media/document/2026-10-19/00-mse-2026-2027-gen-curriculum-sheet_0.pdf', 217, '{}'::text[], null),
('eng-fabe', 'degree', 'BS Food, Agricultural and Biological Engineering', 'College of Engineering', 'College of Engineering, admitted 2026-2027', 132, 2.0, '2026-2027 curriculum sheets (revised 7/2026), 132 credit hours. Choose one specialization: Food, Agricultural, Biological, or Ecological Engineering. Course numbers use the official subject FABENG (the sheets write FABE). A senior exit survey is required. Ohio State requires a 2.00 cumulative GPA to graduate; a D or better passes a course, but some prerequisites need C- or better.', 'https://advising.engineering.osu.edu/current-students/curriculum-sheets-major', 218, '{}'::text[], null),
('eng-fabe-food', 'specialization', 'Food Engineering (FABE)', 'College of Engineering', 'College of Engineering, admitted 2026-2027', null, null, null, 'https://advising.engineering.osu.edu/current-students/curriculum-sheets-major', 219, '{}'::text[], 'eng-fabe'),
('eng-fabe-ag', 'specialization', 'Agricultural Engineering (FABE)', 'College of Engineering', 'College of Engineering, admitted 2026-2027', null, null, null, 'https://advising.engineering.osu.edu/current-students/curriculum-sheets-major', 220, '{}'::text[], 'eng-fabe'),
('eng-fabe-bio', 'specialization', 'Biological Engineering (FABE)', 'College of Engineering', 'College of Engineering, admitted 2026-2027', null, null, null, 'https://advising.engineering.osu.edu/current-students/curriculum-sheets-major', 221, '{}'::text[], 'eng-fabe'),
('eng-fabe-eco', 'specialization', 'Ecological Engineering (FABE)', 'College of Engineering', 'College of Engineering, admitted 2026-2027', null, null, null, 'https://advising.engineering.osu.edu/current-students/curriculum-sheets-major', 222, '{}'::text[], 'eng-fabe'),
('eng-cse', 'degree', 'BS Computer Science and Engineering', 'College of Engineering', 'College of Engineering, admitted 2026-2027', 126, 2.0, 'Requirements for students who entered in or after Autumn 2022 (126 credit hours), from the CSE department''s program page (the college''s linked curriculum sheet was last updated 3/22/2023). Admission to the major requires an application. Every student also picks a CSE specialization, which sets some of the technical electives; BuckAI checks the overall technical elective hours, not each specialization''s list. A program outcomes exit test (POCAT) is required in the graduation term. Ohio State requires a 2.00 cumulative GPA to graduate; a D or better passes a course, but some prerequisites need C- or better.', 'https://cse.osu.edu/prospective-students/undergrad/majors/bs-cse-program-information', 223, '{}'::text[], null),
('eng-chemical', 'degree', 'BS Chemical Engineering', 'College of Engineering', 'College of Engineering, admitted 2026-2027', 126, 2.0, 'Suggested curriculum for students starting in MATH 1151 (126 credit hours). Optional focus areas: Biomolecular, Environmental, or Polymer (through electives). Ohio State requires a 2.00 cumulative GPA to graduate; a D or better passes a course, but some prerequisites need C- or better.', 'https://cbe.osu.edu/curriculum-students-starting-math-1151', 224, '{}'::text[], null),
('eng-ise', 'degree', 'BS Industrial and Systems Engineering', 'College of Engineering', 'College of Engineering, admitted 2026-2027', 127, 2.0, 'Sample curriculum for students admitted Autumn 2023 and after (127 credit hours, including one 3-credit free elective). Choose one technical elective track as your specialization. All students need at least 30 credit hours of math and basic science. Ohio State requires a 2.00 cumulative GPA to graduate; a D or better passes a course, but some prerequisites need C- or better.', 'https://ise.osu.edu/autumn-2023-and-after-sample-curriculum', 225, '{}'::text[], null),
('eng-ise-data', 'specialization', 'Data Analytics & Optimization (ISE track)', 'College of Engineering', 'College of Engineering, admitted 2026-2027', null, null, 'Technical elective track, at least 17 credit hours.', 'https://ise.osu.edu/degrees/undergraduate-program/curriculum-ise-elective-tracks-bsms-information', 226, '{}'::text[], 'eng-ise'),
('eng-ise-supply', 'specialization', 'Supply Chain Management & Logistics (ISE track)', 'College of Engineering', 'College of Engineering, admitted 2026-2027', null, null, 'Technical elective track, at least 15 credit hours.', 'https://ise.osu.edu/degrees/undergraduate-program/curriculum-ise-elective-tracks-bsms-information', 227, '{}'::text[], 'eng-ise'),
('eng-ise-msor', 'specialization', 'Management Systems & Operations Research (ISE track)', 'College of Engineering', 'College of Engineering, admitted 2026-2027', null, null, 'Technical elective track, at least 15 credit hours.', 'https://ise.osu.edu/degrees/undergraduate-program/curriculum-ise-elective-tracks-bsms-information', 228, '{}'::text[], 'eng-ise'),
('eng-ise-mfg', 'specialization', 'Manufacturing (ISE track)', 'College of Engineering', 'College of Engineering, admitted 2026-2027', null, null, 'Technical elective track, at least 15 credit hours.', 'https://ise.osu.edu/degrees/undergraduate-program/curriculum-ise-elective-tracks-bsms-information', 229, '{}'::text[], 'eng-ise'),
('eng-ise-hsid', 'specialization', 'Human Systems Integration & Design (ISE track)', 'College of Engineering', 'College of Engineering, admitted 2026-2027', null, null, 'Technical elective track, at least 15 credit hours.', 'https://ise.osu.edu/degrees/undergraduate-program/curriculum-ise-elective-tracks-bsms-information', 230, '{}'::text[], 'eng-ise'),
('eng-biomedical', 'degree', 'BS Biomedical Engineering', 'College of Engineering', 'College of Engineering, admitted 2026-2027', 131, 2.0, 'From BME''s sample curriculum for students starting in MATH 1151 (the sample plan totals 131 credit hours; confirm the official minimum with your BME advisor). Course numbers use the official subject BIOMEDE. Ohio State requires a 2.00 cumulative GPA to graduate; a D or better passes a course, but some prerequisites need C- or better.', 'https://bme.osu.edu/bme-sample-curriculum-sheets', 231, '{}'::text[], null),
('eng-aviation', 'degree', 'BS Aviation', 'College of Engineering', 'College of Engineering, admitted 2026-2027', 121, 2.0, 'Requirements for students starting Autumn 2026 or later. Two versions: non-flight, or with flight training (Professional Pilot Certification and R-ATP). The sample schedules total about 121 credit hours; confirm the minimum with your aviation advisor. Ohio State requires a 2.00 cumulative GPA to graduate; a D or better passes a course, but some prerequisites need C- or better.', 'https://aviation.osu.edu/majors/bachelor-science-aviation', 232, '{}'::text[], null),
('eng-aviation-nonflight', 'specialization', 'Aviation (non-flight)', 'College of Engineering', 'College of Engineering, admitted 2026-2027', null, null, null, 'https://aviation.osu.edu/b.s.-aviation-non-flight-starting-autumn-2026-or-later', 233, '{}'::text[], 'eng-aviation'),
('eng-aviation-flight', 'specialization', 'Aviation with Flight Training', 'College of Engineering', 'College of Engineering, admitted 2026-2027', null, null, 'Courses marked R-ATP on the department''s page count toward the Restricted Airline Transport Pilot certificate.', 'https://aviation.osu.edu/b.s.-aviation-flight-training-starting-autumn-2026-or-later', 234, '{}'::text[], 'eng-aviation')
